//! bise_proto::words, generated (architect m_27078): one TS file per area
//! for the desktop (`words_<area>.gen.ts`, typed fns, + `words.gen.ts`)
//! and one JSON file per area for the Python tests (`tests/words/`,
//! read by tests/words.py and tests/word_lint.py). Per area, so the
//! chunks that move an area's words never touch the same generated file.

use bise_proto::words::{holes, Word, ALL};
use serde_json::json;
use std::collections::BTreeMap;
use std::fmt::Write;
use std::path::{Path, PathBuf};

/// `tests/words/`: the JSON for the Python tests.
pub fn json_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/words")
}

/// A template as a TS expression over `a`: `"in " + String(a.agent) + "'s thread"`.
fn ts_expr(template: &str) -> String {
    let mut parts = Vec::new();
    let mut rest = template;
    for h in holes(template) {
        let hole = format!("{{{h}}}");
        let i = rest.find(&hole).expect("a hole of this template");
        if i > 0 {
            parts.push(json!(&rest[..i]).to_string());
        }
        parts.push(format!("String(a.{h})"));
        rest = &rest[i + hole.len()..];
    }
    if !rest.is_empty() || parts.is_empty() {
        parts.push(json!(rest).to_string());
    }
    parts.join(" + ")
}

fn ts_word(s: &mut String, w: &Word) {
    let name = w.key.split_once('.').map_or(w.key, |(_, n)| n);
    let doc = w.doc.lines().map(str::trim).filter(|l| !l.is_empty()).collect::<Vec<_>>().join(" ");
    writeln!(s, "  /** {} */", doc.replace("*/", "* /")).unwrap();
    if w.args.is_empty() {
        writeln!(s, "  {name}: {},", json!(w.text)).unwrap();
        return;
    }
    let ty = w.args.iter().map(|a| if *a == "n" && w.one.is_some() { format!("{a}: number") } else { format!("{a}: string | number") }).collect::<Vec<_>>().join("; ");
    let body = match w.one {
        Some(one) => format!("a.n === 1 ? {} : {}", ts_expr(one), ts_expr(w.text)),
        None => ts_expr(w.text),
    };
    writeln!(s, "  {name}: (a: {{ {ty} }}): string => {body},").unwrap();
}

/// `words_<area>.gen.ts` per area and `words.gen.ts`, by file name.
pub fn render_ts(header: fn(&mut String)) -> BTreeMap<String, String> {
    let mut out = BTreeMap::new();
    let mut index = String::new();
    header(&mut index);
    writeln!(index, "// bise_proto::words: the UI words, one module per area (rust/proto/src/words/).").unwrap();
    writeln!(index).unwrap();
    for (area, words) in ALL {
        let mut s = String::new();
        header(&mut s);
        writeln!(s, "// bise_proto::words::{area}: rust/proto/src/words/{area}.rs, never a word typed here.").unwrap();
        writeln!(s).unwrap();
        writeln!(s, "export const {area} = {{").unwrap();
        for w in *words {
            ts_word(&mut s, w);
        }
        writeln!(s, "}} as const;").unwrap();
        out.insert(format!("words_{area}.gen.ts"), s);
        writeln!(index, "export {{ {area} }} from './words_{area}.gen';").unwrap();
    }
    out.insert("words.gen.ts".to_string(), index);
    out
}

/// `<area>.gen.json` per area: `{"_": header, "<key>": {"text", "args", "one"}}`.
pub fn render_json() -> BTreeMap<String, String> {
    ALL.iter()
        .map(|(area, words)| {
            let mut m = serde_json::Map::new();
            m.insert("_".into(), json!(format!("generated by bise-proto (rust/proto/tests/ts.rs) from rust/proto/src/words/{area}.rs, never hand-edited: BISE_PROTO_BLESS=1 cargo test -p bise-proto --features ts --test ts")));
            for w in *words {
                m.insert(w.key.into(), json!({ "text": w.text, "args": w.args, "one": w.one }));
            }
            (format!("{area}.gen.json"), serde_json::to_string_pretty(&serde_json::Value::Object(m)).unwrap() + "\n")
        })
        .collect()
}

#[test]
fn a_template_becomes_a_ts_expression() {
    assert_eq!(ts_expr("in {agent}'s thread"), r#""in " + String(a.agent) + "'s thread""#);
    assert_eq!(ts_expr("{n}"), "String(a.n)");
    assert_eq!(ts_expr("{a} · {b}"), r#"String(a.a) + " · " + String(a.b)"#);
    assert_eq!(ts_expr(""), r#""""#);
}
